(function() {
    'use strict';

    class PandemicLeadershipAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Adaptive Leadership in Crisis';
            this.version = '1.1.0';

            this.PHASE_NAMES = {
                en: ['Initial Shock', 'Stabilization', 'Adaptive Recovery', 'Redesign'],
                es: ['Shock Inicial', 'Estabilizacion', 'Recuperacion Adaptativa', 'Rediseno']
            };

            this.ROUNDS = [
                {
                    phase: 1,
                    title: { en: 'Workforce Announcement', es: 'Comunicado al Personal' },
                    briefing: {
                        en: 'The government has declared a public health emergency. Mandatory office closures take effect in 72 hours. Your operations director has prepared two draft all-hands messages. How will you communicate with your 450 employees?',
                        es: 'El gobierno ha declarado emergencia sanitaria. El cierre obligatorio de oficinas entra en vigor en 72 horas. Tu director de operaciones ha preparado dos borradores de comunicado. ¿Como te comunicaras con tus 450 empleados?'
                    },
                    options: [
                        { value: 1, label: { en: 'Reassuring but vague — business as usual with precautions', es: 'Tranquilizador pero vago — todo sigue igual con precauciones' }, effects: { trust: -5, temperature: -10, resilience: 0, financial: 0, cultural: -5, adaptive: -2 } },
                        { value: 2, label: { en: 'Honest about uncertainty — clear on what you know and will decide', es: 'Honesto sobre la incertidumbre — claro sobre lo que se sabe y se decidira' }, effects: { trust: 5, temperature: 8, resilience: 2, financial: 0, cultural: 3, adaptive: 5 } },
                        { value: 3, label: { en: 'Hybrid — acknowledge uncertainty with an immediate action plan', es: 'Hibrido — reconocer incertidumbre con plan de accion inmediato' }, effects: { trust: 3, temperature: 3, resilience: 1, financial: 0, cultural: 2, adaptive: 3 } }
                    ]
                },
                {
                    phase: 1,
                    title: { en: 'Technology Infrastructure', es: 'Infraestructura Tecnologica' },
                    briefing: {
                        en: 'IT reports that only 40% of staff have company laptops; the rest rely on office desktops. You have 72 hours to enable remote work for the entire workforce. Each option carries different cost and security trade-offs.',
                        es: 'TI reporta que solo el 40% del personal tiene laptops de la empresa; el resto usa equipos de escritorio. Tienes 72 horas para habilitar el trabajo remoto. Cada opcion tiene diferentes implicaciones de costo y seguridad.'
                    },
                    options: [
                        { value: 1, label: { en: 'Emergency laptop procurement at premium cost', es: 'Compra de emergencia de laptops a costo premium' }, effects: { trust: 2, temperature: -3, resilience: 5, financial: -1, cultural: 0, adaptive: 1 } },
                        { value: 2, label: { en: 'BYOD policy with security waivers', es: 'Politica BYOD con exenciones de seguridad' }, effects: { trust: -2, temperature: 0, resilience: 2, financial: 0, cultural: -1, adaptive: 2 } },
                        { value: 3, label: { en: 'Staggered office access with health protocols', es: 'Acceso escalonado a la oficina con protocolos sanitarios' }, effects: { trust: -5, temperature: -3, resilience: -3, financial: 0, cultural: -2, adaptive: -3 } },
                        { value: 4, label: { en: 'Combination — laptops for critical roles, BYOD for support', es: 'Combinacion — laptops para roles criticos, BYOD para soporte' }, effects: { trust: 2, temperature: 2, resilience: 4, financial: -0.5, cultural: 1, adaptive: 3 } }
                    ]
                },
                {
                    phase: 1,
                    title: { en: 'Client Communication', es: 'Comunicacion con Clientes' },
                    briefing: {
                        en: 'Three major clients have called asking about project continuity. You have 120 active clients across financial services, retail, and healthcare. How will you manage the communication to clients during this critical moment?',
                        es: 'Tres clientes principales han llamado preguntando sobre la continuidad de proyectos. Tienes 120 clientes activos en servicios financieros, retail y salud. ¿Como manejaras la comunicacion con clientes en este momento critico?'
                    },
                    options: [
                        { value: 1, label: { en: 'CEO personal calls to all top-10 clients', es: 'Llamadas personales del CEO a los 10 principales clientes' }, effects: { trust: 8, temperature: -2, resilience: 2, financial: 0.5, cultural: 2, adaptive: 0 } },
                        { value: 2, label: { en: 'Delegate to account managers with a unified script', es: 'Delegar a gerentes de cuenta con guion unificado' }, effects: { trust: 2, temperature: 0, resilience: 1, financial: 0, cultural: 1, adaptive: 3 } },
                        { value: 3, label: { en: 'Send a mass email to all clients', es: 'Enviar email masivo a todos los clientes' }, effects: { trust: -5, temperature: -3, resilience: 0, financial: -0.3, cultural: -3, adaptive: -1 } }
                    ]
                },
                {
                    phase: 1,
                    title: { en: 'Crisis Team Formation', es: 'Formacion del Equipo de Crisis' },
                    briefing: {
                        en: 'You need to assemble a crisis management team from eight candidates with varying expertise, emotional intelligence, and organizational influence. The composition of this team will shape every subsequent decision.',
                        es: 'Necesitas formar un equipo de gestion de crisis entre ocho candidatos con diferente experiencia, inteligencia emocional e influencia organizacional. La composicion de este equipo moldeara cada decision posterior.'
                    },
                    options: [
                        { value: 1, label: { en: 'Pure technical experts — operations, IT, finance', es: 'Expertos tecnicos puros — operaciones, TI, finanzas' }, effects: { trust: 0, temperature: -2, resilience: 5, financial: 0.2, cultural: -3, adaptive: -5 } },
                        { value: 2, label: { en: 'Trusted inner circle — loyalists with high CEO alignment', es: 'Circulo de confianza — leales con alta alineacion al CEO' }, effects: { trust: 3, temperature: -5, resilience: 0, financial: 0, cultural: -2, adaptive: -8 } },
                        { value: 3, label: { en: 'Diverse cross-functional team with varied perspectives', es: 'Equipo diverso interfuncional con perspectivas variadas' }, effects: { trust: 2, temperature: 5, resilience: 3, financial: 0, cultural: 5, adaptive: 8 } },
                        { value: 4, label: { en: 'Mixed team with external advisory support', es: 'Equipo mixto con apoyo de asesores externos' }, effects: { trust: 1, temperature: 3, resilience: 4, financial: -0.3, cultural: 3, adaptive: 6 } }
                    ]
                },
                {
                    phase: 2,
                    title: { en: 'Remote Productivity Crisis', es: 'Crisis de Productividad Remota' },
                    briefing: {
                        en: 'After 3 weeks of remote work, billable hours have dropped 28%. The CFO presents three explanations: (A) technology barriers, (B) management style incompatibility with remote supervision, (C) employee anxiety and burnout. You must diagnose the root cause and choose an intervention.',
                        es: 'Tras 3 semanas de trabajo remoto, las horas facturables cayeron 28%. El CFO presenta tres explicaciones: (A) barreras tecnologicas, (B) incompatibilidad del estilo gerencial con la supervision remota, (C) ansiedad y agotamiento de empleados. Debes diagnosticar la causa raiz y elegir una intervencion.'
                    },
                    options: [
                        { value: 1, label: { en: 'Invest in better tools and platforms (technology fix)', es: 'Invertir en mejores herramientas y plataformas (solucion tecnologica)' }, effects: { trust: -3, temperature: -2, resilience: 2, financial: -0.3, cultural: -2, adaptive: -5 } },
                        { value: 2, label: { en: 'Retrain managers for remote leadership (adaptive approach)', es: 'Reentrenar gerentes para liderazgo remoto (enfoque adaptativo)' }, effects: { trust: 5, temperature: 5, resilience: 3, financial: -0.2, cultural: 5, adaptive: 8 } },
                        { value: 3, label: { en: 'Launch employee wellness and support programs', es: 'Lanzar programas de bienestar y apoyo al empleado' }, effects: { trust: 3, temperature: 0, resilience: 1, financial: -0.2, cultural: 2, adaptive: 2 } }
                    ]
                },
                {
                    phase: 2,
                    title: { en: 'The Talent Crisis', es: 'La Crisis de Talento' },
                    briefing: {
                        en: 'Two senior consultants have received job offers from competitors at premium rates. Simultaneously, three analysts request unpaid leave for family caregiving. Your response will set a precedent for the entire organization.',
                        es: 'Dos consultores senior recibieron ofertas de la competencia a tasas premium. Simultaneamente, tres analistas solicitan licencia sin goce para cuidado familiar. Tu respuesta sentara precedente para toda la organizacion.'
                    },
                    options: [
                        { value: 1, label: { en: 'Aggressive counter-offers to retain senior talent', es: 'Contraofertas agresivas para retener talento senior' }, effects: { trust: -3, temperature: 2, resilience: 1, financial: -0.5, cultural: -8, adaptive: -1 } },
                        { value: 2, label: { en: 'Systematic compensation restructuring for all levels', es: 'Reestructuracion sistematica de compensacion para todos los niveles' }, effects: { trust: 3, temperature: 3, resilience: 2, financial: -0.3, cultural: 5, adaptive: 2 } },
                        { value: 3, label: { en: 'Flexible scheduling and caregiving support policy', es: 'Politica de horarios flexibles y apoyo al cuidador' }, effects: { trust: 5, temperature: 3, resilience: 2, financial: -0.1, cultural: 3, adaptive: 5 } },
                        { value: 4, label: { en: 'Do nothing — let market forces decide', es: 'No intervenir — dejar que el mercado decida' }, effects: { trust: -5, temperature: -5, resilience: -3, financial: 0, cultural: -3, adaptive: -2 } }
                    ]
                },
                {
                    phase: 2,
                    title: { en: 'The Resistant Senior Manager', es: 'El Gerente Senior Resistente' },
                    briefing: {
                        en: 'The head of the Bogota office — one of the highest revenue generators — is openly undermining the remote work policy, insisting the team come to the office and dismissing health concerns. Other managers are watching how you respond.',
                        es: 'El director de la oficina de Bogota — uno de los mayores generadores de ingresos — esta saboteando abiertamente la politica de trabajo remoto, insistiendo en que su equipo vaya a la oficina y descartando las preocupaciones de salud. Otros gerentes observan como respondes.'
                    },
                    options: [
                        { value: 1, label: { en: 'Direct confrontation — enforce compliance publicly', es: 'Confrontacion directa — exigir cumplimiento publicamente' }, effects: { trust: 2, temperature: 10, resilience: 1, financial: 0, cultural: 5, adaptive: 3 } },
                        { value: 2, label: { en: 'Private HR-mediated conversation', es: 'Conversacion privada mediada por RRHH' }, effects: { trust: 2, temperature: 3, resilience: 1, financial: 0, cultural: 3, adaptive: 2 } },
                        { value: 3, label: { en: 'Tolerate the deviation in exchange for revenue performance', es: 'Tolerar la desviacion a cambio del rendimiento en ingresos' }, effects: { trust: -5, temperature: -5, resilience: -1, financial: 0.3, cultural: -8, adaptive: -5 } },
                        { value: 4, label: { en: 'Create a special market-based arrangement for Bogota', es: 'Crear un arreglo especial basado en el mercado para Bogota' }, effects: { trust: -2, temperature: -2, resilience: 0, financial: 0.1, cultural: -3, adaptive: -2 } }
                    ]
                },
                {
                    phase: 2,
                    title: { en: 'Financial Stress Management', es: 'Gestion del Estres Financiero' },
                    briefing: {
                        en: 'The CFO presents a cash flow forecast: 5 months of runway at current burn rate, with $8M in receivables at risk if two major clients defer payments. You must decide on financial survival measures — but the wrong cost cuts could destroy capacity at the worst time.',
                        es: 'El CFO presenta una proyeccion de flujo de caja: 5 meses de operacion al ritmo actual, con $8M en cuentas por cobrar en riesgo si dos grandes clientes difieren pagos. Debes decidir medidas de supervivencia financiera — pero recortes equivocados podrian destruir capacidad en el peor momento.'
                    },
                    options: [
                        { value: 1, label: { en: 'Draw credit line and defer partner distributions', es: 'Usar linea de credito y diferir distribuciones a socios' }, effects: { trust: 2, temperature: 0, resilience: 3, financial: 1, cultural: 1, adaptive: 1 } },
                        { value: 2, label: { en: '15% workforce reduction to extend runway', es: 'Reduccion de 15% de la plantilla para extender la operacion' }, effects: { trust: -8, temperature: 10, resilience: -5, financial: 2, cultural: -5, adaptive: -5 } },
                        { value: 3, label: { en: 'Accelerate client collections and cut discretionary costs', es: 'Acelerar cobros a clientes y recortar costos discrecionales' }, effects: { trust: 0, temperature: 3, resilience: 2, financial: 1.5, cultural: 0, adaptive: 0 } },
                        { value: 4, label: { en: 'Combined approach — credit, deferrals, and cost discipline (no layoffs)', es: 'Enfoque combinado — credito, diferimientos y disciplina de costos (sin despidos)' }, effects: { trust: 3, temperature: 3, resilience: 2, financial: 0.5, cultural: 2, adaptive: 2 } }
                    ]
                },
                {
                    phase: 3,
                    title: { en: 'Strategic Pivot or Preserve?', es: 'Pivotar o Preservar?' },
                    briefing: {
                        en: 'A digital transformation boutique has approached MCG with an informal acquisition offer. Simultaneously, a healthcare client offers a large contract to redesign hospital patient flow systems. Your strategy team presents three paths forward — each with very different risk and reward profiles.',
                        es: 'Una boutique de transformacion digital se acerca a MCG con una oferta informal de adquisicion. Simultaneamente, un cliente de salud ofrece un gran contrato para redisenar sistemas de flujo de pacientes. Tu equipo estrategico presenta tres caminos — cada uno con perfiles de riesgo y retorno muy diferentes.'
                    },
                    options: [
                        { value: 1, label: { en: 'Acquire the digital practice and pivot positioning', es: 'Adquirir la practica digital y pivotar el posicionamiento' }, effects: { trust: 0, temperature: 8, resilience: 5, financial: -1, cultural: 0, adaptive: 8 } },
                        { value: 2, label: { en: 'Focus on the healthcare opportunity as revenue stabilizer', es: 'Enfocarse en la oportunidad de salud como estabilizador de ingresos' }, effects: { trust: 2, temperature: 2, resilience: 3, financial: 1.5, cultural: 1, adaptive: 2 } },
                        { value: 3, label: { en: 'Maintain current positioning and wait for market normalization', es: 'Mantener posicionamiento actual y esperar normalizacion del mercado' }, effects: { trust: -2, temperature: -5, resilience: -3, financial: 0, cultural: 0, adaptive: -5 } }
                    ]
                },
                {
                    phase: 3,
                    title: { en: '100-Day Communication', es: 'Comunicacion de 100 Dias' },
                    briefing: {
                        en: 'The crisis team recommends a public 100-Day Update to all stakeholders — employees, clients, investors, and the board. The narrative you choose will define the organizational identity going forward. What framing will you adopt?',
                        es: 'El equipo de crisis recomienda una Actualizacion de 100 Dias para todos los stakeholders — empleados, clientes, inversores y la junta. La narrativa que elijas definira la identidad organizacional. ¿Que enfoque adoptaras?'
                    },
                    options: [
                        { value: 1, label: { en: 'Celebrate wins and minimize failures', es: 'Celebrar logros y minimizar fracasos' }, effects: { trust: -5, temperature: -5, resilience: 0, financial: 0, cultural: -5, adaptive: -2 } },
                        { value: 2, label: { en: 'Balanced honesty — acknowledge losses and celebrate adaptation', es: 'Honestidad equilibrada — reconocer perdidas y celebrar la adaptacion' }, effects: { trust: 5, temperature: 3, resilience: 2, financial: 0, cultural: 5, adaptive: 3 } },
                        { value: 3, label: { en: 'Forward-focused — emphasize future plans and strategic vision', es: 'Enfocado al futuro — enfatizar planes y vision estrategica' }, effects: { trust: 0, temperature: -2, resilience: 1, financial: 0, cultural: -2, adaptive: 2 } }
                    ]
                },
                {
                    phase: 3,
                    title: { en: 'Hybrid Work Design', es: 'Diseno de Trabajo Hibrido' },
                    briefing: {
                        en: 'With restrictions easing, you must design the permanent post-crisis operating model. This decision will shape how MCG works for years. The model must be internally consistent — policies must align with each other and with the organizational culture you want to build.',
                        es: 'Con las restricciones relajandose, debes disenar el modelo operativo permanente post-crisis. Esta decision definira como trabaja MCG por anos. El modelo debe ser internamente consistente — las politicas deben alinearse entre si y con la cultura organizacional que quieres construir.'
                    },
                    options: [
                        { value: 1, label: { en: 'Full return to office with enhanced protocols', es: 'Retorno total a la oficina con protocolos mejorados' }, effects: { trust: -8, temperature: 10, resilience: -2, financial: -0.3, cultural: -5, adaptive: -8 } },
                        { value: 2, label: { en: 'Fully remote with optional office hubs', es: 'Totalmente remoto con hubs opcionales' }, effects: { trust: 3, temperature: 2, resilience: 3, financial: 0.5, cultural: -3, adaptive: 5 } },
                        { value: 3, label: { en: 'Coherent hybrid — structured flexibility with clear norms', es: 'Hibrido coherente — flexibilidad estructurada con normas claras' }, effects: { trust: 5, temperature: 3, resilience: 5, financial: 0.2, cultural: 5, adaptive: 5 } }
                    ]
                },
                {
                    phase: 3,
                    title: { en: 'Burnout Inflection Point', es: 'Punto de Inflexion del Agotamiento' },
                    briefing: {
                        en: 'HR reports alarming data: 38% of employees report working more hours remotely, 22% report increased anxiety, and 3 high performers have resigned citing burnout. The root cause may be structural — not just a wellness problem. How will you intervene?',
                        es: 'RRHH reporta datos alarmantes: 38% trabaja mas horas en remoto, 22% reporta mayor ansiedad, y 3 empleados clave renunciaron por agotamiento. La causa raiz puede ser estructural — no solo un problema de bienestar. ¿Como intervendras?'
                    },
                    options: [
                        { value: 1, label: { en: 'Launch wellness programs and mental health benefits', es: 'Lanzar programas de bienestar y beneficios de salud mental' }, effects: { trust: 1, temperature: -2, resilience: 1, financial: -0.2, cultural: -2, adaptive: -3 } },
                        { value: 2, label: { en: 'Redesign role boundaries and workload structures', es: 'Redisenar limites de roles y estructuras de carga de trabajo' }, effects: { trust: 5, temperature: 3, resilience: 3, financial: 0, cultural: 5, adaptive: 8 } },
                        { value: 3, label: { en: 'Mandatory time off and reduced client commitments', es: 'Tiempo libre obligatorio y reduccion de compromisos con clientes' }, effects: { trust: 3, temperature: -5, resilience: 2, financial: -0.3, cultural: 2, adaptive: 2 } }
                    ]
                },
                {
                    phase: 4,
                    title: { en: 'New Organizational Structure', es: 'Nueva Estructura Organizacional' },
                    briefing: {
                        en: 'It is time to redesign the organizational structure for the post-crisis world. Each model has different implications for resilience, cultural integrity, and revenue potential. The choice must align with the strategic direction you chose earlier.',
                        es: 'Es hora de redisenar la estructura organizacional para el mundo post-crisis. Cada modelo tiene diferentes implicaciones para resiliencia, integridad cultural y potencial de ingresos. La eleccion debe alinearse con la direccion estrategica que elegiste antes.'
                    },
                    options: [
                        { value: 1, label: { en: 'Maintain hierarchy with remote-enabled protocols', es: 'Mantener jerarquia con protocolos habilitados para remoto' }, effects: { trust: 0, temperature: -3, resilience: -2, financial: 0, cultural: -2, adaptive: -3 } },
                        { value: 2, label: { en: 'Project-team fluid network — agile and decentralized', es: 'Red fluida de equipos de proyecto — agil y descentralizada' }, effects: { trust: 2, temperature: 5, resilience: 5, financial: 0, cultural: 3, adaptive: 8 } },
                        { value: 3, label: { en: 'Hub-and-spoke hybrid — regional autonomy with central coordination', es: 'Modelo hub-and-spoke — autonomia regional con coordinacion central' }, effects: { trust: 3, temperature: 3, resilience: 5, financial: 0.2, cultural: 5, adaptive: 5 } },
                        { value: 4, label: { en: 'Radical platform model with embedded client teams', es: 'Modelo de plataforma radical con equipos integrados en clientes' }, effects: { trust: 0, temperature: 8, resilience: 3, financial: -0.5, cultural: -2, adaptive: 10 } }
                    ]
                },
                {
                    phase: 4,
                    title: { en: 'Capability Investment', es: 'Inversion en Capacidades' },
                    briefing: {
                        en: 'You have $2M in investment capacity to build new capabilities. Where you allocate this investment will position MCG for the next chapter. Your earlier strategic choices shape which investments generate the highest return.',
                        es: 'Tienes $2M de capacidad de inversion para construir nuevas capacidades. Donde asignes esta inversion posicionara a MCG para el proximo capitulo. Tus decisiones estrategicas anteriores influyen en que inversiones generan mayor retorno.'
                    },
                    options: [
