        initialize(state) {
            var _fresh = !state.history || state.history.length === 0;
            if (_fresh || !state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    trust: 70,
                    temperature: 50,
                    resilience: 65,
                    financialHealth: 7.0,
                    culturalIntegrity: 60,
                    adaptiveCapacity: 45,
                    trustHistory: [],
                    temperatureHistory: [],
                    resilienceHistory: [],
                    financialHistory: [],
                    culturalHistory: [],
                    adaptiveHistory: [],
                    periodsInOptimalZone: 0
                };
            }
            if (_fresh || !state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    choice: 1
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var _submitBtn = document.getElementById('nextPeriodBtn');
            if (_submitBtn && _submitBtn.disabled) { return false; }

            var select = document.getElementById('decisionSelect');
            if (select) decisions.choice = parseInt(select.value);
            if (!decisions.choice) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('decision_warning'), 'warning'
                );
                return false;
            }
            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var lang = this._lang();
            var chosen = null;
            for (var i = 0; i < round.options.length; i++) {
                if (round.options[i].value === d.choice) {
                    chosen = round.options[i];
                    break;
                }
            }
            if (!chosen) chosen = round.options[0];
            var eff = chosen.effects;

            state.domainState.trust = Math.max(0, Math.min(100, state.domainState.trust + (eff.trust || 0)));
            state.domainState.temperature = Math.max(0, Math.min(100, state.domainState.temperature + (eff.temperature || 0)));
            state.domainState.resilience = Math.max(0, Math.min(100, state.domainState.resilience + (eff.resilience || 0)));
            state.domainState.financialHealth = Math.max(0, Math.min(10, state.domainState.financialHealth + (eff.financial || 0)));
            state.domainState.culturalIntegrity = Math.max(0, Math.min(100, state.domainState.culturalIntegrity + (eff.cultural || 0)));
            state.domainState.adaptiveCapacity = Math.max(0, Math.min(100, state.domainState.adaptiveCapacity + (eff.adaptive || 0)));

            if (state.domainState.temperature >= 45 && state.domainState.temperature <= 65) {
                state.domainState.periodsInOptimalZone += 1;
            }

            state.domainState.trustHistory.push(state.domainState.trust);
            state.domainState.temperatureHistory.push(state.domainState.temperature);
            state.domainState.resilienceHistory.push(state.domainState.resilience);
            state.domainState.financialHistory.push(state.domainState.financialHealth);
            state.domainState.culturalHistory.push(state.domainState.culturalIntegrity);
            state.domainState.adaptiveHistory.push(state.domainState.adaptiveCapacity);

            var feedbackPanel = document.getElementById('feedbackPanel');
            var feedbackText = document.getElementById('feedbackText');
            if (feedbackPanel && feedbackText) {
                var msgs = [];
                if (state.domainState.temperature > 65) {
                    msgs.push(window.mySimulation.t('hint_high_temp'));
                }
                if (state.domainState.temperature < 45) {
                    msgs.push(window.mySimulation.t('hint_low_temp'));
                }
                if (state.domainState.trust < 40) {
                    msgs.push(window.mySimulation.t('hint_low_trust'));
                }
                if (state.domainState.financialHealth < 3) {
                    msgs.push(window.mySimulation.t('hint_financial_danger'));
                }
                if (msgs.length > 0) {
                    feedbackText.innerHTML = msgs.join('<br>');
                    feedbackPanel.style.display = 'block';
                } else {
                    feedbackPanel.style.display = 'none';
                }
            }

            // v1.1.0: prevent double-submit re-entrancy (double-applied effects / duplicated
            // history rows). Re-enabled in _updateBriefing when the next period renders.
            var _submitBtn = document.getElementById('nextPeriodBtn');
            if (_submitBtn) { _submitBtn.disabled = true; }

            var self = this;
            var nextPeriod = state.currentPeriod + 1;
            if (nextPeriod <= (state.maxPeriods || 15)) {
                setTimeout(function() {
                    self._updateBriefing({ currentPeriod: nextPeriod });
                }, 500);
            }

            return {
                period: state.currentPeriod,
                phase: round.phase,
                decisionLabel: chosen.label[lang] || chosen.label['en'],
                trust: Math.round(state.domainState.trust),
                temperature: Math.round(state.domainState.temperature),
                resilience: Math.round(state.domainState.resilience),
                financialHealth: parseFloat(state.domainState.financialHealth.toFixed(1)),
                culturalIntegrity: Math.round(state.domainState.culturalIntegrity),
                adaptiveCapacity: Math.round(state.domainState.adaptiveCapacity)
            };
        }

